param([string]$DbHost="127.0.0.1",[string]$DbPort="5432",[string]$DbName="osa_db",[string]$DbUser="postgres")
$ErrorActionPreference="Stop"; $Psql="psql"
Write-Host "========================================="
Write-Host " OSA — P7J v2 DRY RUN TEST"
Write-Host "========================================="
function Run-TestSql{param([string]$Sql) Write-Host ""; Write-Host ">>> Test SQL"; & $Psql -h $DbHost -p $DbPort -U $DbUser -d $DbName -v ON_ERROR_STOP=1 -c $Sql; if($LASTEXITCODE -ne 0){throw "Erreur dry-run P7J v2"}}
Run-TestSql "SELECT CASE WHEN to_regclass('rf.isa_decision_alert_cap_policy') IS NOT NULL THEN 'OK' ELSE 'KO' END check_alert_cap_policy, CASE WHEN to_regclass('ma.v_isa_decision_priority_engine') IS NOT NULL THEN 'OK' ELSE 'KO' END check_priority_engine, CASE WHEN to_regclass('ma.v_isa_intervention_decision_matrix') IS NOT NULL THEN 'OK' ELSE 'KO' END check_matrix, CASE WHEN to_regclass('ma.v_isa_decision_country_year') IS NOT NULL THEN 'OK' ELSE 'KO' END check_country, CASE WHEN to_regclass('ma.v_isa_decision_readiness') IS NOT NULL THEN 'OK' ELSE 'KO' END check_readiness;"
Run-TestSql "SELECT COUNT(*) AS decision_engine_rows FROM ma.v_isa_decision_priority_engine;"
Run-TestSql "SELECT COUNT(*) AS decision_matrix_rows FROM ma.v_isa_intervention_decision_matrix;"
Run-TestSql "SELECT COUNT(*) AS country_decision_rows FROM ma.v_isa_decision_country_year;"
Run-TestSql "SELECT COUNT(*) AS readiness_rows FROM ma.v_isa_decision_readiness;"
Run-TestSql "SELECT COUNT(*) AS critical_nulls FROM ma.v_isa_decision_priority_engine WHERE country_iso3 IS NULL OR year IS NULL OR pillar_code IS NULL OR decision_priority_score IS NULL OR decision_confidence_score IS NULL OR decision_priority_class IS NULL OR decision_timing_code IS NULL;"
Run-TestSql "SELECT COUNT(*) AS out_of_bounds_scores FROM ma.v_isa_decision_priority_engine WHERE decision_priority_score<0 OR decision_priority_score>1 OR decision_confidence_score<0 OR decision_confidence_score>1;"
Run-TestSql "SELECT COUNT(*) AS invalid_priority_classes FROM ma.v_isa_decision_priority_engine WHERE decision_priority_class NOT IN ('DECISION_CRITICAL','DECISION_HIGH','DECISION_STANDARD','DECISION_MONITOR');"
Run-TestSql "SELECT COUNT(*) AS invalid_timing_codes FROM ma.v_isa_decision_priority_engine WHERE decision_timing_code NOT IN ('IMMEDIATE_0_3_MONTHS','SHORT_TERM_3_12_MONTHS','MEDIUM_TERM_1_3_YEARS','MONITORING_ONLY');"
Run-TestSql "SELECT COUNT(*) AS yellow_to_critical_should_be_zero FROM ma.v_isa_decision_priority_engine WHERE sovereign_alert_level='YELLOW' AND decision_priority_class='DECISION_CRITICAL';"
Run-TestSql "SELECT COUNT(*) AS green_to_high_or_critical_should_be_zero FROM ma.v_isa_decision_priority_engine WHERE sovereign_alert_level='GREEN' AND decision_priority_class IN ('DECISION_HIGH','DECISION_CRITICAL');"
Run-TestSql "SELECT COUNT(DISTINCT country_iso3) nb_countries, COUNT(DISTINCT year) nb_years, COUNT(DISTINCT pillar_code) nb_pillars FROM ma.v_isa_decision_priority_engine;"
Run-TestSql "SELECT decision_priority_class, COUNT(*) nb FROM ma.v_isa_decision_priority_engine GROUP BY decision_priority_class ORDER BY decision_priority_class;"
Run-TestSql "SELECT country_decision_class, COUNT(*) nb FROM ma.v_isa_decision_country_year GROUP BY country_decision_class ORDER BY country_decision_class;"
Write-Host ""; Write-Host "✅ P7J v2 dry-run terminé avec succès"
